pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    B c;
    function setUp() public { c = new B(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != c.owner());
        amount = bound(amount, 1, 1_000_000 ether);

        uint256 ownerBefore = c.owner().balance;
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.go{value: amount}() {
            assertEq(address(c).balance, 0);
            assertGt(c.owner().balance, ownerBefore);
        } catch {
        }
    }
}
